1: /*
2:  * billing-export.js
3:  * ------------------------------------------------------------------
4:  * Nightly billing export of the todo list.
5:  * Written 2014 (rk), ported to node 2017 (dt). No tests, sorry.
6:  *
7:  * BILLING INGEST (BIL-7) PARSES THIS OUTPUT BYTE FOR BYTE.
8:  * Read docs/EXPORT-FORMAT.md before touching anything in here.
9:  * ------------------------------------------------------------------
10:  */
11: 'use strict';
12: 
13: var MAX_LEN = 40;           // BIL-7 field width, incl. the ~ marker
14: var g_sHeader = 'ID,TITLE,DONE';
15: var CRLF = '\r\n';
16: var LEGACY_V1 = false;      // v1 used ';' separators. kept for rollback (dt)
17: 
18: // 000042
19: function pad_id(nId) {
20:   var s = '' + nId;
21:   while (s.length < 6) {
22:     s = '0' + s;
23:   }
24:   return s;
25: }
26: 
27: function clean_title(sTitle) {
28:   var s = sTitle;
29:   if (s.length > MAX_LEN) {
30:     s = s.substr(0, MAX_LEN - 1) + '~';
31:   }
32:   // spreadsheet guard, see SEC-31. billing opens these in excel
33:   var c = s.charAt(0);
34:   if (c == '=' || c == '+' || c == '-' || c == '@') {
35:     s = "'" + s;
36:   }
37:   return s;
38: }
39: 
40: // open items first, then done ones. by id inside each group (BIL-9)
41: function sort_rows(aTodos) {
42:   var a = aTodos.slice(0);
43:   for (var i = 0; i < a.length; i++) {
44:     for (var j = 0; j < a.length - 1 - i; j++) {
45:       var x = a[j], y = a[j + 1];
46:       var bSwap = false;
47:       if (x.completed && !y.completed) bSwap = true;
48:       else if (!!x.completed == !!y.completed && x.id > y.id) bSwap = true;
49:       if (bSwap) {
50:         a[j] = y;
51:         a[j + 1] = x;
52:       }
53:     }
54:   }
55:   return a;
56: }
57: 
58: function build_row(oTodo) {
59:   var sep = LEGACY_V1 ? ';' : ',';
60:   return pad_id(oTodo.id) + sep + clean_title(oTodo.title) + sep + (oTodo.completed ? 'Y' : 'N');
61: }
62: 
63: function toCsv(aTodos) {
64:   var out = g_sHeader + CRLF;
65:   var rows = sort_rows(aTodos || []);
66:   for (var i = 0; i < rows.length; i++) {
67:     out += build_row(rows[i]) + CRLF;
68:   }
69:   return out;
70: }
71: 
72: module.exports = {
73:   toCsv: toCsv,
74:   pad_id: pad_id,
75:   clean_title: clean_title
76: };

